  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'court-interdict-cata-codeta-taxi-violence-return-date-2026-10-30',
  'High Court restrains CATA and CODETA after deadly taxi violence',
  'Traffic', '2026-10-30', 'Cape Town ETC', 'https://www.capetownetc.com/news/western-cape-tougher-stance-taxi-industry-disputes/',
  'A provisional High Court order bans violence, blockades and route takeovers by CATA and CODETA, with a return date of 20 November 2026.',
  'A provisional order from the Western Cape High Court now binds the Cape Amalgamated Taxi Association (CATA) and the Congress of Democratic Taxi Associations (CODETA). The province''s Mobility Department applied for it after fresh outbreaks of taxi violence.

The order also reaches the named office bearers of both bodies, as well as the associations and individual members linked to them. Among the things it forbids are violence and intimidation, blocking roads, seizing routes unlawfully, damaging property and getting in the way of public or private transport. Carrying guns or other dangerous weapons is also limited at ranks and inside minibus taxis on the routes concerned. The order is provisional but takes effect immediately.

The matter returns to the High Court on 20 November 2026, with a 10:00 start, when the two bodies can argue against the order becoming permanent. According to the reports, the Mobility Department said it had no choice but to approach the court after other attempts to stop the violence failed.

Separately, the CATA Langa Inter-township Taxi Association has had its registration put on hold for six months by the Provincial Taxi Registrar, after an inquiry looked at illegal operations around Epping. The registrar found the association knowingly let members invade routes and did not rein them in. For the duration, members of that association are barred from seeking any operating licence changes, whether new, renewed, amended, transferred or temporary. Commuters on affected routes should expect further updates as the case continues.',
  NULL, NULL, NULL,
  '["https://www.capetownetc.com/news/western-cape-tougher-stance-taxi-industry-disputes/", "https://smilefm.co.za/wc-mobility-granted-interim-interdict-against-taxi-violence/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'strand-square-renamed-strand-muslim-community-square-2026-10-30',
  'Strand square officially renamed Strand Muslim Community Square',
  'Community', '2026-10-30', 'Cape Town ETC', 'https://www.capetownetc.com/news/strand-square-new-name-muslim-heritage/',
  'Ben Friedman Square in Strand was formally renamed Strand Muslim Community Square at a ceremony on Wednesday, 28 October.',
  'A public square in Strand that was known as Ben Friedman Square now carries the name Strand Muslim Community Square. The renaming was marked at a ceremony on Wednesday, 28 October.

The City of Cape Town says Council approved the new name on 30 July 2026, after a public participation process in which a range of views were heard. The ceremony drew Alderman Eddie Andrews, who is the City''s Deputy Mayor and chairs its Naming Committee, as well as Chantal Cerfontein, who chairs Subcouncil 8, and a mix of religious leaders and residents.

The change was initiated by the Strand Muslim community, which says its roots in the area go back more than 200 years and marked its 200th anniversary in 2023. The community sought the new name to recognise that long presence and to remember families who were forcibly removed from the area under apartheid. Three mosques stand around the square.

The City says the renaming is intended to protect the community''s heritage, encourage healing and reconciliation, and give residents a stronger sense of belonging. The renaming committee described it as a step towards restorative justice.',
  NULL, NULL, NULL,
  '["https://www.capetownetc.com/news/strand-square-new-name-muslim-heritage/", "https://bolanderlifestyle.co.za/news/2026-10-30-ben-friedman-square-renamed-strand-muslim-community-square-in-strand/"]',
  'agent'
);
